import * as trees from "../trees";
import {Node} from "../trees";
import {keys} from "../keys";
import $ from "jquery";
import * as colors from "../colors";

export type TreeView = {
    treeview(action: string, ...args: unknown[]): Node[];
} & JQuery;

export default function setupTreeView(callback: () => void) {
    const treeSetupCallback = function treeSetupCallback(srcTree: Node[], callback: () => void) {
        const selectedNodes = function selectedNodes(treeView: TreeView): Node[] {
            return treeView.treeview('getSelected', 0);
        };

        const deselectValue = function deselectValue(value: Node, treeView: TreeView) {
            treeView.treeview('unselectNode', [value, {silent: true}]);
        };

        const isSameNode = function isSameNode(node: Node, value: Node, treeView: TreeView) {
            if (node.text !== value.text) {
                deselectValue(value, treeView);
            } else {
                // eslint-disable-next-line no-prototype-builtins
                const testNodeHasNodes = node.hasOwnProperty('nodes');
                // eslint-disable-next-line no-prototype-builtins
                if (testNodeHasNodes === value.hasOwnProperty('nodes')) {
                    if (testNodeHasNodes) {
                        if (node.nodes.length === value.nodes.length) {
                            for (let i = 0; i < node.nodes.length; i++) {
                                isSameNode(node.nodes[i], value.nodes[i], treeView);
                            }
                        } else {
                            deselectValue(value, treeView);
                        }
                    }
                } else {
                    deselectValue(value, treeView);
                }
            }
        };

        const generateTreeViewNodeUnselectionHandler = function generateTreeViewNodeUnselectionHandler(treeViews: TreeView[]) {
            return function (event: unknown, node: Node) {
                if (typeof trees.callbacks.projectView.nodeUnselected === 'function')
                    trees.callbacks.projectView.nodeUnselected();

                if (keys.ctrl.pressed) return;
                treeViews.forEach(function(treeView: TreeView) {
                    const selected = selectedNodes(treeView);
                    if (selected.length < 1)  return;

                    selected.forEach(function (value: Node) {
                        deselectValue(value, treeView);
                    });

                    treeView.treeview('selectNode', [node.nodeId, { silent: true}]);
                });
            };
        };

        const generateTreeViewNodeSelectionHandler = function generateTreeViewNodeSelectionHandler(treeViews: TreeView[]) {
            return function (event: unknown, node: Node) {
                if (typeof trees.callbacks.projectView.nodeSelected === 'function')
                    trees.callbacks.projectView.nodeSelected();

                if (keys.ctrl.pressed) return;
                treeViews.forEach(function(treeView) {
                    const selected = selectedNodes(treeView);

                    selected.forEach(function (value) {
                        isSameNode(node, value, treeView);
                        trees.callbacks.projectView.nodeSelected();
                    });
                });
            };
        };
        const $file: TreeView = <{
            treeview(action: string, ...args: unknown[]): Node[]
        } & JQuery<HTMLElement>>$('#file-tree');
        const nodeSelected = generateTreeViewNodeSelectionHandler([$file]);
        const nodeUnselected = generateTreeViewNodeUnselectionHandler([$file]);
        // eslint-disable-next-line @typescript-eslint/ban-ts-comment
        // @ts-ignore
        $file.treeview(trees.defaultParameter(srcTree, nodeSelected, nodeUnselected, colors.backColor, colors.hoverColor));

        if (typeof callback === 'function') {
            callback();
        }
    };
    trees.get(treeSetupCallback, callback);
}