import $ from "jquery";

const env = window.env;

const _allFiles = new Map();
export const allFiles: string[] = [];
export let disabledFiles: string[] = [];

export function isFileEnabled(value: string): boolean {
    return value.split('\n')
        .filter(line => line.trim().length > 0)
        .filter(line => !line.startsWith('// ')).length > 0;
}

export function updateFile(fileName: string, value: string): void {
    const newFileEnabled = isFileEnabled(value);
    const oldFileDisabled = disabledFiles.includes(fileName);
    if (newFileEnabled && oldFileDisabled) {
        disabledFiles = disabledFiles.filter(file => file !== fileName);
    } else if (!newFileEnabled && !oldFileDisabled) {
        disabledFiles.push(fileName);
    }
}

const loadFiles = function () {
    $.get(env.urls.URI_FILE_GET_TREE).then((data) => {
        const splitData = data.match(/BOUNDARY ([\w-]+)\n/)[1];
        const files = data.split(`\nBOUNDARY ${splitData}`).slice(2);
        files
            .map((file: string): [string, string] => {
                const filename = file.match(/ ([^\n]+)\n/)[1];
                const data = file.split('\n').slice(1).join('\n');
                allFiles.push(filename);
                return [filename, data]
            })
            .filter(([filename]: [string]) => filename.endsWith('.java'))
            .forEach(([filename, data]: [string, string]) => _allFiles.set(filename, data));
        _allFiles.forEach((value, key) => {
            const enabled = isFileEnabled(value);
            if (!enabled) {
                disabledFiles.push(key);
            }
        });
    });
};
loadFiles();

export const annotatedFiles = allFiles;

