import {Modifier, Variable, VariableScope} from "./ace_worker/variable-scope";
import {Ace} from "ace-builds";

const env = window.env;

const Identifier = 'Identifier';
const DOT = 'DOT';
const LPAREN = 'LPAREN';
const RPAREN = 'RPAREN';
const COMMA = 'COMMA';

let autoCompleteDisabled = !env.settings.get('autocompleteEnabled');
export let autoCompleteDisabledReason = env.settings.get('autocompleteEnabled') ? null : 'user';

export class FtcCompleter implements Ace.Completer {
    engaged: boolean
    instance: FtcLangTools
    private firstRun: boolean;

    constructor(instance: FtcLangTools) {
        this.instance = instance;
        this.firstRun = false;
    }

    _findCompletionsFor(priorType: Type, prefix: string, validCompletions: Ace.Completion[]): void {
        if (!(priorType !== null && typeof priorType !== 'undefined')) return;

        const possibleFieldsForType = this.instance.possibleFieldsForType(priorType);
        for (const field in possibleFieldsForType) {
            // eslint-disable-next-line no-prototype-builtins
            if (!possibleFieldsForType.hasOwnProperty(field)) continue;
            if (field.indexOf(prefix) === 0) {
                validCompletions.push({
                    caption: field,
                    value: field,
                    score: 700,
                    meta: this.instance.classNameFromFullClassName(possibleFieldsForType[field].type).replace(/\$/g, '.')
                });
            }
        }

        const possibleMethodsForType = this.instance.possibleMethodsForType(priorType);
        for (const method in possibleMethodsForType) {
            // eslint-disable-next-line no-prototype-builtins
            if (!possibleMethodsForType.hasOwnProperty(method)) continue;
            if (method.indexOf(prefix) === 0) {
                possibleMethodsForType[method].forEach((value: Method) => {
                    const params = value.params.map((fullClass: string) =>
                        this.instance.classNameFromFullClassName(fullClass).replace(/\$/g, '.')).join(', ');
                    let snippet = method + '(' + value.params.map(function (t, index) {
                        return `$\{${index + 1}:${t}}`;
                    }).join(', ') + ')';
                    // Add a semicolon and go to the next line if it is not possible to add anything else to the statement
                    if (value.type === 'void') snippet += ';\n${' + value.params.length + 1 + '}';
                    validCompletions.push({
                        caption: method + '(' + params + ')',
                        snippet: snippet,
                        score: 800,
                        meta: this.instance.classNameFromFullClassName(value.type).replace(/\$/g, '.')
                    });
                });
            }
        }
    }

    getCompletions(editor: Ace.Editor, session: Ace.EditSession, pos: Ace.Position, prefix: string, callback: (arg0: null, arg1: Ace.Completion[]) => void) {
        try {
            const timeStart = performance.now();
            const index = env.editor.session.getDocument().positionToIndex(pos, 0);
            const currentVariables = this.instance.validVariablesUnderIndex(index);
            const currentToken = this.instance.tokenUnderIndex(index);

            const currentTokens = this.instance.currentTokens;
            const lastToken = currentTokens[currentTokens.length - 1];

            this.instance.completer.engaged = false;
            if (autoCompleteDisabled || currentToken === null || !(currentToken.type === Identifier || currentToken.type === DOT || currentToken.type === COMMA || currentToken.type === RPAREN)) {
                callback(null, []);
                return;
            }

            // Check if the editor tokens are aligned with the values the user sees
            // We're adding 1 because of the index versus length differences
            if (lastToken.stop + 1 - env.editor.session.getDocument().getValue().trim().length != 0) {
                return;
            }

            let validCompletions: Ace.Completion[] = [];
            let field;
            let method: string;
            let priorType;
            if (currentTokens[currentToken.index - 1].type === DOT) {
                this.instance.completer.engaged = true;
                priorType = this.instance.detectTypeForToken(currentTokens[currentToken.index - 2]);
                this._findCompletionsFor(priorType, prefix, validCompletions);
            } else if (currentToken.type === DOT) {
                priorType = this.instance.detectTypeForToken(currentTokens[currentToken.index - 1]);
                this._findCompletionsFor(priorType, prefix, validCompletions);
            } else if (currentToken.type === COMMA || currentToken.type === RPAREN) {
                if (currentTokens[currentToken.index - 1].type === Identifier && currentTokens[currentToken.index - 2].type === DOT) {
                    priorType = this.instance.detectTypeForToken(currentTokens[currentToken.index - 3]);
                    this._findCompletionsFor(priorType, prefix, validCompletions);
                }
            } else {
                const completedFields = [];
                currentVariables.forEach(function (value) {
                    if (value.id.indexOf(prefix) === 0) {
                        completedFields.push(value.id);
                        validCompletions.push({value: value.id, score: 1000, meta: value.type});
                    }
                });

                const possibleFieldsForType = this.instance.possibleFieldsForType(this.instance.thisType);
                for (field in possibleFieldsForType) {
                    // eslint-disable-next-line no-prototype-builtins
                    if (!possibleFieldsForType.hasOwnProperty(field)) continue;
                    if (field.indexOf(prefix) !== 0 || completedFields.indexOf(field) >= 0) continue;
                    completedFields.push(field);
                    validCompletions.push({
                        value: field, score: 800,
                        meta: this.instance.classNameFromFullClassName(possibleFieldsForType[field].type)
                    });
                }

                const possibleMethodsForType = this.instance.possibleMethodsForType(this.instance.thisType);
                for (method in possibleMethodsForType) {
                    // eslint-disable-next-line no-prototype-builtins
                    if (!possibleMethodsForType.hasOwnProperty(method)) continue;
                    if (method.indexOf(prefix) === 0) {
                        possibleMethodsForType[method].forEach((value) => {
                            const params = value.params.map((fullClass) =>
                                this.instance.classNameFromFullClassName(fullClass).replace(/\$/g, '.')
                            ).join(', ');
                            let snippet = method + '(' + value.params.map(function (t, index) {
                                return `$\{${index + 1}:${t}}`;
                            }).join(', ') + ')';
                            // Add a semicolon and go to the next line if it is not possible to add anything else to the statement
                            if (value.type === 'void') snippet += ';\n${' + value.params.length + 1 + '}';
                            validCompletions.push({
                                caption: method + '(' + params + ')',
                                snippet: snippet,
                                score: 900,
                                meta: this.instance.classNameFromFullClassName(value.type).replace(/\$/g, '.')
                            });
                        });
                    }
                }

                validCompletions = validCompletions.concat(
                    this.instance.autoImport.knownTypeIds.filter(function (value) {
                        return value.indexOf(prefix) === 0;
                    }).map(function (value: string) {
                        return {name: value, value: value, score: 500, meta: value};
                    })
                );
            }

            const sortedCompletions = validCompletions.sort(function (lhs, rhs) {
                if (lhs.score === rhs.score) {
                    let lhsValue = "";
                    if ("snippet" in lhs && lhs.snippet) {
                        lhsValue = lhs.snippet;
                    } else if ("value" in lhs && lhs.value) {
                        lhsValue = lhs.value
                    }

                    let rhsValue = "";
                    if ("snippet" in rhs && rhs.snippet) {
                        rhsValue = rhs.snippet;
                    } else if ("value" in rhs && rhs.value) {
                        rhsValue = rhs.value
                    }

                    return (lhsValue).localeCompare(rhsValue);
                }

                return lhs.score - rhs.score;
            });
            this.instance.completer.engaged = sortedCompletions.length !== 0;
            callback(null, sortedCompletions);

            if (!this.firstRun) {
                const timeToCompletion = performance.now() - timeStart;
                this.firstRun = true;
                // todo: the time this function should actually take is < 25ms, after updating Ace the time > 50ms
                // timeToCompletion should be less than 100 ms, otherwise this editor is going to be unusably slow.
                // 100ms is roughly double the time this function should actually take
                if (!env.settings.get('autocompleteForceEnabled') && timeToCompletion > 100) {
                    autoCompleteDisabled = true;
                    autoCompleteDisabledReason = 'perf';
                    console.warn('Disabling OnBotJava autocomplete, due to performance reasons');
                    env.editor.setOption('enableBasicAutocompletion', false);
                    env.editor.setOption('enableSnippets', false);
                    env.editor.setOption('enableLiveAutocompletion', false);
                    // eslint-disable-next-line @typescript-eslint/ban-ts-comment
                    // @ts-ignore
                    env.langTools.setCompleters([]);
                }
            }
        } catch (ex) {
            console.error(ex);
        }
    }

}

type Method = {
    type: string;
    params: string[];
    modifier: Modifier;
    isStatic: boolean;
}

type MethodCall = {
    identifier: FtcToken;
    lparen: FtcToken,
    params: FtcToken[],
    rparen: FtcToken
}

export type FtcToken = {
    type: string;
    line: number;
    start: number;
    stop: number;
    index: number;
    text: string;
}

class AutoImportTools {
    classToPackageMap: { [key: string]: Type[] };
    knownTypeIds: string[];

    constructor() {
        this.classToPackageMap = {};
        this.knownTypeIds = [];
    }

    updateClassToPackageMap(): void {
        // eslint-disable-next-line @typescript-eslint/no-this-alias
        const instance = this;
        $.get(env.urls.URI_JS_AUTOCOMPLETE, function (data) {
            if (typeof data === 'string') {
                data = JSON.parse(data);
            }
            instance.classToPackageMap = data;
            instance.knownTypeIds = [];
            for (const classOrInterfaceType in instance.classToPackageMap) {
                // eslint-disable-next-line no-prototype-builtins
                if (!instance.classToPackageMap.hasOwnProperty(classOrInterfaceType)) continue;
                instance.knownTypeIds.push(classOrInterfaceType);
                instance.classToPackageMap[classOrInterfaceType].forEach(function (type: Type) {
                    type.name = classOrInterfaceType;
                });
            }
        });
    }
}

declare type Field = {
    foo?: string;
    modifier: Modifier;
    name: string;
    type: string;
    isStatic: boolean;
};

declare type Type = {
    primitiveClass?: Type;
    interfaces: string[];
    fields: { [key: string]: Field }
    methods: { [key: string]: Method[] };
    parentClass: string;
    packageName: string;
    name: string;
    classNameToUse?: string;
    primitive?: boolean;
    modifier: Modifier;
    staticContext: boolean;
};

function checkArgs(expr: unknown, name: string) {
    if (!expr) {
        throw new Error(name + ' is not valid');
    }
}

class FtcLangTools {
    autoImport: AutoImportTools;
    completer: FtcCompleter;
    thisType: Type;
    autoCompleteDisabled: boolean;
    currentVariables: { scopes: VariableScope[], variables: Variable[] };
    currentTokens: FtcToken[];
    currentImports: string[];
    currentPackageName: string;
    currentClassName: string;
    currentSuperClass: string;
    currentInterfaces: string[];
    private readonly cache: { [key: string]: Type };

    constructor() {
        this.autoImport = new AutoImportTools();
        this.completer = new FtcCompleter(this);
        this.cache = {};

        this.thisType = {
            fields: {},
            interfaces: [],
            methods: {},
            modifier: "PUBLIC",
            name: "",
            packageName: "",
            parentClass: "java.lang.Object",
            staticContext: true,
        };
        this.currentPackageName = this.thisType.packageName;
        this.currentTokens = [];
        this.currentVariables = {
            scopes: [],
            variables: [],
        };
        this.currentImports = [];
        this.currentClassName = this.thisType.name;
        this.currentInterfaces = [];
        this.currentSuperClass = this.thisType.parentClass;
    }

    tokenUnderIndex(index: number): FtcToken | null {
        if (this.currentTokens === null) return null;
        let tokenUnderCursor: FtcToken;
        for (let i = 0; i < this.currentTokens.length; i++) {
            const token = this.currentTokens[i];
            if (token.start < index) tokenUnderCursor = token;
            if (token.stop >= index) return tokenUnderCursor;
        }

        return null;
    }

    tokenUnderCursor(offset?: number): FtcToken {
        if (!offset) offset = 0;
        const index = env.editor.session.getDocument().positionToIndex(env.editor.getCursorPosition(), 0) + offset;
        return this.tokenUnderIndex(index);
    }

    findScopeInIndex(currentScopes: VariableScope[], index: number): Variable[] {
        for (const scope of currentScopes) {
            if (scope.start < index && scope.stop >= index) {
                const variablesFromCurrentScope = scope.variables;
                return variablesFromCurrentScope.concat(this.findScopeInIndex(scope.scopes, index));
            }
        }

        return [];
    }

    validVariablesUnderIndex(index: number, line?: number): Variable[] {
        if (this.currentVariables === null) {
            return [];
        }
        if (!line) {
            line = env.editor.session.getDocument().indexToPosition(index, 0).row;
        }

        const currentVariables = this.findScopeInIndex(this.currentVariables.scopes, index);
        return this._cleanupVariables(currentVariables, line);
    }

    validVariablesUnderCursor(offset?: number): Variable[] {
        if (!offset) offset = 0;
        const cursorPosition = env.editor.getCursorPosition();
        const index = env.editor.session.getDocument().positionToIndex(cursorPosition, 0) + offset;
        return this.validVariablesUnderIndex(index, cursorPosition.row + 1);
    }

    validVariablesForToken(token: FtcToken): Variable[] {
        return this.validVariablesUnderIndex(token.start, token.line);
    }

    private _cleanupVariables(possibleVariables: Variable[], forLine: number): Variable[] {
        return possibleVariables.filter((possible) => possible.decType === 'field' || possible.line < forLine)
            .map(x => ({
                level: x.level,
                decType: x.decType,
                id: x.id,
                line: x.line,
                type: x.type,
                // Removes the scope since we shouldn't need it, and it makes the output more readable
                scope: undefined
            }));
    }

    methodFromPossibleMethods(methodCallParts: {
        lparen: FtcToken;
        rparen: FtcToken;
    }, possibleMethods: Method[]): Method {
        const paramTypes = this.getArgumentTypesFromMethod(methodCallParts.lparen, methodCallParts.rparen);
        let selectedMethod = null;
        possibleMethods.forEach((value) => {
            if (paramTypes.length !== value.params.length) return;

            if (paramTypes.length === 0) selectedMethod = value;
            let validSolution = true;
            for (let i = 0; i < paramTypes.length; i++) {
                if (!this.isTypeInstanceOf(this.typeFromFullClassName(value.params[i]), paramTypes[i])) {
                    validSolution = false;
                    break;
                }
            }

            if (validSolution) selectedMethod = value;
        });
        return selectedMethod;
    }

    detectTypeForToken(token: FtcToken | null, variables?: Variable[]): Type | null {
        if (token === null) return null;
        if (variables === null || typeof variables === 'undefined') variables = this.validVariablesForToken(token);
        if (this.isPartOfMethod(token)) {
            const methodIdentifier: FtcToken = this.methodIdentifierFor(token);
            const currentTokens = this.currentTokens;
            const index = methodIdentifier.index;
            const resolveAgainstThis = (currentTokens[index - 1].type === DOT && currentTokens[index - 2].type === 'THIS') || currentTokens[index - 1].type !== DOT;
            let prefixType: Type;
            let possibleMethods;
            let method;
            let methodCallParts;
            if ((token.type === LPAREN || token.type === RPAREN) && !this.isPartOfMethod(token)) {
                const lparen = token.type === LPAREN ? token : this.findMatchingToken(token);
                const rparen = token.type === RPAREN ? token : this.findMatchingToken(token);
                // Check for a cast at this point
                if (currentTokens[lparen.index + 1].type === LPAREN) {
                    const leftCastParen = currentTokens[lparen.index + 1];
                    const rightCastParen = this.findMatchingToken(currentTokens[lparen.index + 1]);
                    if (rightCastParen === rparen || rightCastParen === null) return null;

                    if (currentTokens[lparen.index + 2].type === LPAREN) {
                        return this.detectTypeForToken(currentTokens[lparen.index + 2]);
                    }

                    let typeString = '';
                    let typeId: Type = null;
                    for (let i = leftCastParen.index + 1; i < rightCastParen.index; i++) {
                        if (currentTokens[i].type === DOT) {
                            typeString += '.';
                        } else if (currentTokens[i].type === Identifier) {
                            typeString += currentTokens[i].text;
                            if (typeString.indexOf('.') < 0) {
                                typeId = this.typeForClassName(typeString);
                            } else {
                                const typeComps = typeString.split('.');
                                let possibleTrys = typeComps.length;
                                while (possibleTrys > 0 && (typeId === null || typeof typeId === 'undefined')) {
                                    let test = '';
                                    for (let j = typeComps.length - possibleTrys - 1; j < typeComps.length; j++) {
                                        test += typeComps[j];
                                        if (j + 1 !== typeComps.length) test += '.';
                                    }
                                    typeId = this.typeForClassName(test);
                                    if (typeId === null || typeof typeId === 'undefined') {
                                        typeId = this.typeFromFullClassName(test);
                                    }
                                    possibleTrys--;
                                }
                            }
                        } else {
                            typeId = null;
                            break;
                        }
                    }
                }

                // Jump to the end to see if we can get a type from just inside the expression, basically by getting the type of the next-to-last token
                return this.detectTypeForToken(currentTokens[rparen.index - 1]);
            } else if (!resolveAgainstThis && this.isPartOfMethod(currentTokens[index - 2]) && currentTokens[this.methodIdentifierFor(currentTokens[index - 2]).index - 1].type === DOT) {
                methodCallParts = this._getPartsOfMethodCall(currentTokens[index - 2]);
                prefixType = this.detectTypeForToken(this.methodIdentifierFromMethodCallParts(methodCallParts), variables);
                if (prefixType !== null && typeof prefixType !== 'undefined') {
                    const possibleFieldsForTypeElement = this.possibleMethodsForType(prefixType)[methodIdentifier.text];
                    // We don't know a valid field for this type by name
                    if (typeof possibleFieldsForTypeElement === 'undefined' || possibleFieldsForTypeElement === null) return null;

                    return this.typeFromFullPackageId(possibleFieldsForTypeElement[0].type);
                }
            } else if (!resolveAgainstThis && currentTokens[index - 1].type === DOT && currentTokens[index - 2].type === Identifier) {
                methodCallParts = this._getPartsOfMethodCall(currentTokens[index - 2]);
                prefixType = this.detectTypeForToken(this.methodIdentifierFromMethodCallParts(methodCallParts), variables);
                if (prefixType !== null && typeof prefixType !== 'undefined') {
                    possibleMethods = this.possibleMethodsForType(prefixType)[methodIdentifier.text];
                    // If true, we don't know the valid methods for this type by name
                    if (typeof possibleMethods === 'undefined') return null;

                    method = this.methodFromPossibleMethods(methodCallParts, possibleMethods);
                    return this.typeFromFullPackageId(method.type);
                }
            } else if (resolveAgainstThis) {
                prefixType = this.thisType;
                methodCallParts = this._getPartsOfMethodCall(currentTokens[index - 2]);
                possibleMethods = this.possibleFieldsForType(prefixType)[methodIdentifier.text];
                // We don't know the valid methods for this type by name
                if (typeof possibleMethods === 'undefined') {
                    return null;
                }
                method = this.methodIdentifierFromMethodCallParts(methodCallParts);
                return this.typeFromFullPackageId(method.type);
            } else {
                return null;
            }
        } else if (token.type === Identifier) {
            if (this.currentTokens[token.index - 1].type === DOT) { // This should a field of a type
                const prefixType = this.detectTypeForToken(this.currentTokens[token.index - 2], variables);
                // This is a field of the type found in prefixType, because we have verified that this is not a method, so what else can it be?
                // eslint-disable-next-line @typescript-eslint/no-this-alias
                const instance = this;
                let field;
                if (prefixType !== null && typeof prefixType !== 'undefined') {
                    field = this.possibleFieldsForType(prefixType)[token.text];
                    if (field) {
                        return this.typeFromFullPackageId(field.type);
                    } else {
                        const possibleSubclasses = this.autoImport.knownTypeIds.filter(function (t) {
                            return (t.indexOf(prefixType.name + '$') === 0 || t.indexOf('$' + prefixType.name + '$') > 0) &&
                                t.lastIndexOf('$' + token.text) === t.lastIndexOf('$');
                        });

                        if (possibleSubclasses.length > 1) console.warn('Multiple subclasses possible for ' + prefixType.name + '.' + token.text);
                        if (possibleSubclasses[0])
                            return instance.typeForClassName(possibleSubclasses[0]);
                    }
                } else {
                    return null;
                }
            } else {
                let searchElement = token.text;
                let matchingVariables = variables.filter(function (value) {
                    return value.id === token.text;
                });

                let maxLevel = 0;
                matchingVariables.forEach(function (variable) {
                    if (variable.level > maxLevel) maxLevel = variable.level;
                });

                matchingVariables = matchingVariables.filter(function (variable) {
                    return maxLevel === variable.level;
                });
                // There should only be one left with proper Java
                if (matchingVariables.length > 0) {
                    searchElement = matchingVariables[0].type;
                    if (this.autoImport.knownTypeIds.indexOf(searchElement) >= 0) {
                        let type = this.typeForClassName(searchElement);
                        type = {...type, staticContext: false}
                        return type;
                    } else {
                        return null;
                    }
                }

                const field = this.possibleFieldsForType(this.thisType)[token.text];
                if (field) {
                    let type = this.typeFromFullClassName(field.type);
                    type = {...type, staticContext: false}
                    return type;
                }

                let lastAttempt = this.typeForClassName(token.text) || this.typeFromFullClassName(token.text);
                if (lastAttempt) {
                    lastAttempt = {...lastAttempt, staticContext: true}
                    return lastAttempt;
                }
            }
        } else if (token.type === 'THIS') {
            let thisType1 = this.thisType;
            thisType1 = {...thisType1, staticContext: false}
            return thisType1;
        } else if (token.type === 'SUPER') {
            let superType = this.typeFromFullClassName(this.thisType.parentClass);
            superType = {...superType, staticContext: false}
            return superType;
        }

        return null;
    }

    detectTypeUnderCursor(): Type {
        const variables = this.validVariablesUnderCursor();
        const tokenUnderCursor = this.tokenUnderCursor();
        return this.detectTypeForToken(tokenUnderCursor, variables);
    }

    findMatchingToken(token: FtcToken): FtcToken {
        let depth = 0;
        let selectedToken = null;
        let i = token.index;
        const left = token.type.charAt(0) === 'L';
        // We need to swap left and right to get the matching element
        const matchTo = (left ? 'R' : 'L') + token.type.substr(1);

        if (left) {
            for (; i < this.currentTokens.length; i++) {
                selectedToken = this.currentTokens[i];
                if (selectedToken.type === matchTo) {
                    ++depth;
                } else {
                    if (depth === 0) break;
                    --depth;
                }
            }
        } else {
            for (; i >= 0; i--) {
                selectedToken = this.currentTokens[i];
                if (selectedToken.type === matchTo) {
                    if (depth === 0) break;
                    --depth;
                } else {
                    ++depth;
                }
            }
        }

        return selectedToken;
    }

    isPartOfMethod(startToken: FtcToken) {
        const index = startToken.index;
        const currentTokens = this.currentTokens;
        let matching;

        if (startToken.type === Identifier) {
            if (index - 1 < 0) return false;
            if (currentTokens[index - 1].type === DOT && currentTokens[index + 1].type === LPAREN) {
                matching = this.findMatchingToken(currentTokens[index + 1]);
                return matching !== null;
            }
        }

        if (startToken.type === LPAREN) {
            if (index - 2 < 0) return false;
            if (currentTokens[index - 2].type === DOT && currentTokens[index - 1].type === Identifier) {
                matching = this.findMatchingToken(currentTokens[index]);
                return matching !== null;
            }
        }


        if (startToken.type === RPAREN) {
            matching = this.findMatchingToken(currentTokens[index]);
            if (matching !== null) {
                const matchedIndex = matching.index;
                if (matchedIndex - 2 < 0) {
                    return false;
                }

                return currentTokens[matchedIndex - 1].type === Identifier && currentTokens[matchedIndex - 2].type === DOT;
            }
        }

        return false;
    }

    methodIdentifierFor(startToken: FtcToken): FtcToken {
        const partsOfMethod = this._getPartsOfMethodCall(startToken);
        return this.methodIdentifierFromMethodCallParts(partsOfMethod);
    }

    methodIdentifierFromMethodCallParts(methodCall: MethodCall): FtcToken | null {
        if (methodCall.identifier !== null && methodCall.identifier.type === Identifier) {
            return methodCall.identifier;
        }

        return null;
    }

    _getPartsOfMethodCall(startToken: FtcToken): MethodCall | null {
        const index = startToken.index;
        const currentTokens = this.currentTokens;
        let matching;
        const result: MethodCall = {
            identifier: null,
            lparen: null,
            params: [],
            rparen: null
        };

        if (startToken.type === Identifier) {
            matching = this.findMatchingToken(currentTokens[index + 1]);
            result.identifier = startToken;
            result.lparen = currentTokens[index + 1];
            result.rparen = matching;
        }

        if (startToken.type === LPAREN) {
            if (index - 2 < 0) return null;
            if (currentTokens[index - 2].type === DOT && currentTokens[index - 1].type === Identifier) {
                matching = this.findMatchingToken(currentTokens[index]);
                if (matching.index < 1) return result;
                result.identifier = currentTokens[index - 1];
                result.lparen = startToken;
                result.rparen = matching;
            }
        }

        if (startToken.type === RPAREN) {
            matching = this.findMatchingToken(currentTokens[index]);
            if (matching !== null) {
                if (matching.index < 1) return result;
                result.identifier = currentTokens[matching.index - 1];
                result.lparen = matching;
                result.rparen = startToken;
            }
        }

        return result;
    }

    getArgumentTypesFromMethod(methodCallLparen: FtcToken, methodCallRparen: FtcToken) {
        const paramTypes: Type[] = [];
        for (let i = methodCallLparen.index + 1; i < methodCallRparen.index && i < this.currentTokens.length; i++) {
            if (this.currentTokens[i + 1].type === COMMA || this.currentTokens[i + 1] === methodCallRparen) {
                const token = this.currentTokens[i];
                paramTypes.push(this.detectTypeForToken(token));
            }
        }

        return paramTypes;
    }

    sanitizePrimitiveTypes(fullClassName: string): Type {
        if (fullClassName === 'void') return null;
        let classNameToUse = fullClassName;
        const primitive = (['int', 'boolean', 'long', 'float', 'double', 'byte', 'short', 'char'].indexOf(fullClassName) >= 0);
        if (primitive) {
            switch (fullClassName) {
                case 'int':
                    classNameToUse = 'Integer';
                    break;
                case 'boolean':
                    classNameToUse = 'Boolean';
                    break;
                case 'long':
                    classNameToUse = 'Long';
                    break;
                case 'float':
                    classNameToUse = 'Float';
                    break;
                case 'double':
                    classNameToUse = 'Double';
                    break;
                case 'byte':
                    classNameToUse = 'Byte';
                    break;
                case 'short':
                    classNameToUse = 'Short';
                    break;
                case 'char':
                    classNameToUse = 'Character';
                    break;
            }
        }
        return {
            interfaces: [],
            methods: {},
            fields: {},
            name: fullClassName,
            packageName: "java.lang",
            parentClass: "java.lang.Object",
            classNameToUse: classNameToUse,
            modifier: 'PUBLIC',
            primitive: primitive,
            staticContext: true,
        };
    }

    fullClassNameFromType(type: Type) {
        checkArgs(type, 'type')
        if (type.packageName === '' || !type.packageName) return type.name;
        return type.packageName + '.' + type.name;
    }

    isFullPackageName(classNameToUse: string) {
        checkArgs(classNameToUse, 'classNameToUse')
        return classNameToUse.indexOf('.') >= 0;
    }

    typeFromFullPackageId(fullClassName: string) {
        checkArgs(fullClassName, 'fullClassName')
        let className;
        let packageName;
        const primitiveCheck = this.sanitizePrimitiveTypes(fullClassName);
        if (primitiveCheck === null) return null;
        const classNameToUse = primitiveCheck.classNameToUse;
        const primitive = primitiveCheck.primitive;

        if (this.isFullPackageName(classNameToUse)) {
            className = this.classNameFromFullClassName(classNameToUse);
            packageName = this.packageNameFromFullClassName(classNameToUse);
        } else {
            className = classNameToUse;
            // All Java primitive types are in the java.lang package
            if (primitive) {
                packageName = 'java.lang';
            } else {
                packageName = '';
            }
        }

        const possibleClasses = this.autoImport.classToPackageMap[className];
        if (!possibleClasses) {
            console.log('Failed to lookup class "' + className + '". Please open an issue, if you think it should be resolved');
            return null;
        }

        for (let i = 0; i < possibleClasses.length; i++) {
            if (possibleClasses[i].packageName === packageName) {
                const correctClass: Type = possibleClasses[i];
                if (primitive) {
                    if (!correctClass.primitiveClass) {
                        correctClass.primitiveClass = {
                            interfaces: [],
                            parentClass: "java.lang.Object",
                            methods: correctClass.methods,
                            fields: {},
                            primitive: true,
                            packageName: 'java.lang',
                            name: fullClassName,
                            modifier: 'PUBLIC',
                            staticContext: true,
                        };
                    }

                    return correctClass.primitiveClass;
                }

                return correctClass;
            }
        }

        return undefined;
    }

    typeFromPossibleTypes(possibleTypes: Type[], className: string, packageName?: string): Type | null {
        checkArgs(possibleTypes, 'possibleTypes')
        checkArgs(className, 'className')

        if (!packageName && packageName !== '') {
            const importedClassPackagesNames: { [key: string]: string } = {};
            // eslint-disable-next-line @typescript-eslint/no-this-alias
            const instance = this;
            this.currentImports.forEach(function (importClass: string) {
                importedClassPackagesNames[instance.classNameFromFullClassName(importClass)] = instance.packageNameFromFullClassName(importClass);
            });

            const $index = className.indexOf('$');
            packageName = importedClassPackagesNames[$index >= 0 ? className.substr(0, $index) : className];
        }

        if (!packageName) {
            return this.typeFromPossibleTypes(this.autoImport.classToPackageMap[className], className, 'java.lang');
        }

        for (let i = 0; i < possibleTypes.length; i++) {
            const possibleType = possibleTypes[i];
            if (possibleType.name === className && possibleType.packageName === packageName) {
                return possibleType;
            }
        }

        return null;
    }

    typeForClassName(className: string): Type {
        checkArgs(className, 'className')
        // This checks if the class is like an `int` and we can unbox that into an `Integer` class
        const primitiveCheck = this.sanitizePrimitiveTypes(className);
        // If className === 'void', we return null
        if (primitiveCheck === null) return null;
        if (className.indexOf(']') >= 0) {
            return {
                fields: {
                    length: {
                        isStatic: false,
                        modifier: 'PUBLIC',
                        name: 'length',
                        type: 'int'
                    }
                },
                interfaces: [],
                methods: {},
                modifier: 'PUBLIC',
                name: className,
                packageName: 'java.lang',
                parentClass: 'java.lang.Object',
                staticContext: true,
            };
        }

        // Handles the cases like List<T> where T is a type parameter. We only want this first bit for our completions,
        // so we extract that `List` in this case.
        if (className.match(/\w+<.+>/)) {
            primitiveCheck.classNameToUse = primitiveCheck.classNameToUse.replace(/(\w+)<.+>/, "$1");
        }
        return this.typeFromPossibleTypes(this.autoImport.classToPackageMap[primitiveCheck.classNameToUse], primitiveCheck.classNameToUse);
    }

    // an alias todo: remove
    typeFromFullClassName(x: string): Type {
        return this.typeFromFullPackageId(x);
    }

    possibleMethodsForType(type: Type): { [key: string]: Method[] } {
        const cacheHit = this.cacheForType(type, "methods");
        if (type !== this.thisType && typeof cacheHit !== 'undefined') {
            return cacheHit.methods;
        }

        const parentType = this.typeFromFullClassName(type.parentClass);
        if (type === this.typeFromFullClassName('java.lang.Object')) {
            return type.methods;
        }

        const parentMethods = this.possibleMethodsForType(parentType);
        const usedInterfaces = type.interfaces.map((value) => {
            return this.possibleMethodsForType(this.typeFromFullClassName(value));
        });

        const addElementIfMissing = function (array1: unknown[], element: unknown) {
            if (array1.filter(function (value) {
                return value === element;
            }).length === 0) {
                array1.push(element);
            }
        };

        const possibleMethods: Map<string, Method[]> = new Map<string, Method[]>();
        for (const method in type.methods) {
            // eslint-disable-next-line no-prototype-builtins
            if (!type.methods.hasOwnProperty(method)) continue;

            if (!possibleMethods.has(method)) {
                possibleMethods.set(method, []);
            }
            possibleMethods.set(method, possibleMethods.get(method).concat(type.methods[method]));
        }

        for (const method in parentMethods) {
            // eslint-disable-next-line no-prototype-builtins
            if (!parentMethods.hasOwnProperty(method)) continue;
            const possibleMethod = possibleMethods.get(method);
            if (Array.isArray(possibleMethod)) {
                parentMethods[method].forEach(function (value) {
                    addElementIfMissing(possibleMethod, value);
                });
            } else {
                possibleMethods.set(method, parentMethods[method]);
            }
        }

        usedInterfaces.forEach(function (usedInterface) {
            for (const method in usedInterface) {
                // eslint-disable-next-line no-prototype-builtins
                if (!usedInterface.hasOwnProperty(method)) continue;
                if (!possibleMethods.has(method)) {
                    possibleMethods.set(method, usedInterface[method]);
                } else {
                    usedInterface[method].forEach(function (value) {
                        addElementIfMissing(possibleMethods.get(method), value);
                    });
                }
            }
        });

        const rawPossibleMethods: { [key: string]: Method[]} = {};
        for (const method of possibleMethods.keys()) {
            rawPossibleMethods[method] = possibleMethods.get(method);
        }

        // Never cache the object we are working on
        if (this.thisType !== type) {
            type.methods = rawPossibleMethods;
            this.updateCacheForType(type, "methods");
        }

        return rawPossibleMethods;
    }

    possibleFieldsForType(type: Type) {
        const cacheHit = this.cacheForType(type, "fields");
        if (type !== this.thisType && typeof cacheHit !== 'undefined') {
            return cacheHit.fields;
        }

        const parentType = this.typeFromFullClassName(type.parentClass);
        if (type === this.typeFromFullClassName('java.lang.Object')) {
            return type.fields;
        }

        const parentFields = this.possibleFieldsForType(parentType);
        // eslint-disable-next-line @typescript-eslint/no-this-alias
        const instance = this;
        const usedInterfaces = type.interfaces.map(function (value) {
            return instance.possibleFieldsForType(instance.typeFromFullClassName(value));
        });

        const fields: { [key: string]: Field } = {};
        let field;

        usedInterfaces.forEach(function (usedInterface) {
            for (field in usedInterface) {
                // eslint-disable-next-line no-prototype-builtins
                if (!usedInterface.hasOwnProperty(field)) continue;
                fields[field] = usedInterface[field];
            }
        });

        for (field in parentFields) {
            // eslint-disable-next-line no-prototype-builtins
            if (!parentFields.hasOwnProperty(field)) continue;
            fields[field] = parentFields[field];
        }

        for (field in type.fields) {
            // eslint-disable-next-line no-prototype-builtins
            if (!type.fields.hasOwnProperty(field)) continue;
            fields[field] = type.fields[field];
        }
        type.fields = fields;

        // Never cache the object we are working on
        if (this.thisType !== type) {
            this.updateCacheForType(type, "fields");
        }

        return fields;
    }

    packageNameFromFullClassName(fullClassName: string) {
        if (this.isFullPackageName(fullClassName)) {
            return fullClassName.substring(0, fullClassName.lastIndexOf('.'));
        } else {
            return '';
        }
    }

    classNameFromFullClassName(fullClassName: string) {
        if (this.isFullPackageName(fullClassName)) {
            return fullClassName.substr(fullClassName.lastIndexOf('.') + 1);
        } else {
            return fullClassName;
        }
    }

    isTypeInstanceOf(testType: Type, testParentType: Type) {
        if (testType === testParentType) return true;

        const parentType = this.typeFromFullClassName(testType.parentClass);
        // Given that above we check if testType === testParentType, if the test type is a java.lang.Object
        // no other class is a valid parent type
        if (this.fullClassNameFromType(testType) === 'java.lang.Object') {
            return false;
        }

        if (parentType === testParentType) {
            return true;
        } else if (this.isTypeInstanceOf(parentType, testParentType)) {
            return true;
        } else {
            // eslint-disable-next-line @typescript-eslint/no-this-alias
            const instance = this;
            const usedInterfaces = testType.interfaces.map(function (value) {
                return instance.typeFromFullClassName(value);
            });
            for (let i = 0; i < usedInterfaces.length; i++) {
                if (this.isTypeInstanceOf(usedInterfaces[i], testParentType)) return true;
            }
        }

        return false;
    }

    updateThisProps(superClassName: string, interfaceNames: string[], methods: Map<string, {
        type: string,
        name: string,
        modifier: Modifier,
        params: string[]
    }[]>) {
        checkArgs(superClassName, 'superClassName')
        checkArgs(interfaceNames, 'interfaceNames')
        checkArgs(methods, 'methods')

        this.thisType = {
            fields: {},
            interfaces: [],
            methods: {},
            modifier: "PUBLIC",
            name: "",
            packageName: "",
            parentClass: "java.lang.Object",
            staticContext: true,
        };
        const thisFields: { [key: string]: Field } = {};
        this.currentVariables.scopes
            .flatMap(x => x.variables)
            .filter((variable) => variable.decType === 'field')
            .forEach((value) => {
                const type: Type = this.typeForClassName(value.type);
                thisFields[value.id] = {
                    type: type.packageName + '.' + type.name,
                    name: value.id,
                    modifier: 'PUBLIC',
                    isStatic: false,
                };
        });
        this.thisType.fields = thisFields;
        this.thisType.packageName = this.currentPackageName;
        this.thisType.name = this.currentClassName;

        // Handles the case when extends is referencing a fully qualified class name
        // If that name includes a '.' character, it's probably fully qualified class name.
        // This doesn't happen the case where the class name is referencing an inner class
        if (superClassName.includes('.')) {
            this.thisType.parentClass = this.fullClassNameFromType(this.typeFromFullClassName(superClassName));
        } else {
            this.thisType.parentClass = this.fullClassNameFromType(this.typeForClassName(superClassName));
        }
        this.thisType.interfaces = interfaceNames.map((t) => {
            const type = this.typeForClassName(t);
            return this.fullClassNameFromType(type);
        });

        const thisMethods: { [key: string]: Method[] } = {};
        for (const method of methods.keys()) {
            thisMethods[method] = methods.get(method).map((t) => {
                if (t.type !== 'void') {
                    const type = this.typeForClassName(t.type);
                    t.type = this.fullClassNameFromType(type);
                }
                t.modifier = (t.modifier.toUpperCase() as Modifier);
                const returnType: Method = {
                    ...t,
                    isStatic: false,
                }
                return returnType;
            });
        }

        this.thisType.methods = thisMethods;

        // For some reason, our autocompleter needs to be manually re-called more often then it actually does, so we force it to update
        // eslint-disable-next-line @typescript-eslint/ban-ts-comment
        // @ts-ignore
        if (env.editor.completer && env.editor.completer.activated) {
            // eslint-disable-next-line @typescript-eslint/ban-ts-comment
            // @ts-ignore
            env.editor.completer.updateCompletions();
        }
    }

    cacheForType(type: Type, calculation: "fields" | "methods"): Type | undefined {
        const key = this.fullClassNameFromType(type);
        const cacheKey = `${key}:${calculation}`;

        // eslint-disable-next-line no-prototype-builtins
        if (this.cache.hasOwnProperty(cacheKey)) {
            if (typeof this.cache[cacheKey] !== 'object') {
                return undefined;
            }
        }

        return this.cache[cacheKey];
    }

    updateCacheForType(type: Type, calculation: "fields" | "methods"): Type | undefined {
        const key = this.fullClassNameFromType(type);
        const cacheKey = `${key}:${calculation}`;
        this.cache[cacheKey] = type;
        return this.cache[key];
    }
}

export default FtcLangTools;