import $ from 'jquery';


declare global {
    const loadRcInfo: (callback: () => void) => void;
    const isFtcRobotController: () => boolean;
}

const env = window.env;

export const errors     = {
    FILE_NOT_FOUND: "error=file_not_found",
    FILE_NOT_DIRECTORY: "error=file_not_directory",
}
env.errors = errors;

const installedEditorThemes = ['light', 'dark'];
const editorTheme = 'obj'; //env.settings.get('theme');
env.installedEditorThemes = installedEditorThemes;
env.editorTheme = editorTheme;

const getParameterByName = function getParameterByName(name: string): string {
    const url = window.location.href;
    name = name.replace(/[[\]]/g, "\\$&");
    const regex = new RegExp("[?&]" + name + "(=([^&#]*)|&|#|$)");
    const results = regex.exec(url);
    if (!results) return null;
    if (!results[2]) return '';
    return decodeURIComponent(results[2].replace(/\+/g, " "));
};
env.getParameterByName = getParameterByName;

export const fixedUriEncode = function fixedUriEncode(code: string): string {
    return encodeURIComponent(code).replace(/[!'()*]/g, (c) => {
        return '%' + c.charCodeAt(0).toString(16);
    });
};
env.fixedUriEncode = fixedUriEncode;

export const baseUrlRoot = (() => document.URL.substring(0, document.URL.indexOf(env.urls.URI_JAVA_PREFIX)))();
env.baseUrlRoot = baseUrlRoot;

export const javaUrlRoot = (function getJavaUrlRoot() {
    const currentUri = document.URL;
    return currentUri.substring(0, currentUri.indexOf(env.urls.URI_JAVA_PREFIX) + env.urls.URI_JAVA_PREFIX.length);
})();
env.javaUrlRoot = javaUrlRoot;

export function extractDocumentIdFromUri(currentUri: string): string {
    const javaEditorWithParamQuery = env.urls.URI_JAVA_EDITOR + '?';
    if (currentUri.indexOf(javaEditorWithParamQuery) === -1) {
        return '';
    }

    let paramFileName = getParameterByName("f");
    if (paramFileName) {
        return paramFileName;
    }

    paramFileName = currentUri.substring(currentUri.indexOf(javaEditorWithParamQuery) + (javaEditorWithParamQuery).length);
    if (paramFileName !== '.java') {
        return paramFileName;
    }

    return '';
}
env.extractDocumentIdFromUri = extractDocumentIdFromUri;

export const documentIdToTabName = function documentIdToTabName(): void {
    // no-op
};
env.documentIdToTabName = documentIdToTabName;

const _isFtcRobotController: boolean | JQuery.Deferred<boolean, unknown, unknown> = (function () {
    if (typeof isFtcRobotController !== 'function') {
        console.warn('util.js has not been loaded');
        return false;
    }

    const promise = $.Deferred();
    loadRcInfo(function () {
        env._isFtcRobotController = isFtcRobotController();
        promise.resolve(env._isFtcRobotController);
    });

    return promise;
})();
env._isFtcRobotController = _isFtcRobotController;

env.whenFtcRobotController = function <T>(yes: T, no: T): T {
    return no;
};

export const waitForFtcRobotControllerDetect = function(callback: () => void): void {
    if (typeof callback !== 'function') return;
    $.when(_isFtcRobotController).then(callback);
};
env.waitForFtcRobotControllerDetect = waitForFtcRobotControllerDetect;