import $ from "jquery";
import * as utils from "./utils";

let srcFiles: Node[] = null
let jarFiles: Node[] = null;

export type Node = {
    nodeId?: number;
    parent: string;
    parentFile: string;
    file: string;
    folder: boolean;
    icon: string;
    text: string;
    href?: string;
    nodes?: Node[];
    parentNode?: Node;
};
const env = window.env;
type FileTrie = Map<string, FileTrie>;

export function findInSourceFiles(file: string) {
    return parse._findNodeInTree(file, srcFiles);
}

export function findInLibraries(file: string) {
    return parse._findNodeInTree(file, jarFiles);
}
export function defaultParameter(dataTree: Node[], nodeSelected: () => void, nodeUnselected: () => void, backColor: string, hoverColor: string) {
    return {
        data: dataTree,
        expandIcon: 'fa fa-caret-right',
        collapseIcon: 'fa fa-caret-down',
        backColor: backColor,
        onhoverColor: hoverColor,
        enableLinks: true,
        showBorder: false,
        multiSelect: true,
        onNodeSelected: nodeSelected,
        onNodeUnselected: nodeUnselected,
        onRendered: function() {
            $('li.node-file-tree a').click(e => {
                const target = $(e.target);
                const targetId = utils.extractDocumentIdFromUri(target.attr('href'));
                if (env.changeDocument && targetId) {
                    e.preventDefault();
                    env.changeDocument(targetId);
                }
            });
        }
    };
}

export const callbacks = { // for the UI system
    projectView: {
        // eslint-disable-next-line @typescript-eslint/no-empty-function
        nodeSelected: () => {},
        // eslint-disable-next-line @typescript-eslint/no-empty-function
        nodeUnselected: () => {}
    }
};

type LibrariesTree = { src: string[], jars: string[] };
export const parse = {
    _findNodeInTree: function _findInTree(file: string, tree: Node[]) {
        let restToMatch = file;
        let currNode: Node = null;
        for (const node of tree) {
            console.log(restToMatch, node.parentFile)
            if (restToMatch.startsWith(node.parentFile + node.file + "/")) {
                restToMatch = restToMatch.substr(node.parentFile.length + node.file.length + 1);
                console.log(restToMatch);
                currNode = node;
            }
        }

        if (currNode === null) {
            return utils.errors.FILE_NOT_FOUND;
        }

        let foundNode = true;
        while (foundNode) {
            foundNode = false;
            for (const node of currNode.nodes) {
                if (node.folder && restToMatch.startsWith(node.file + "/")) {
                    if (restToMatch === node.file + "/") {
                        return node;
                    }
                    restToMatch = restToMatch.substr(node.file.length + 1);
                    console.log(restToMatch);
                    currNode = node;
                    foundNode = true;
                    break;
                    // this only happens since we sometimes skip directories
                    // in the file tree view
                } else if (file.startsWith(node.parentFile + node.file)) {
                    if (file === node.parentFile + node.file) {
                        return node;
                    }
                    restToMatch = file.substr(node.parentFile.length + node.file.length + 1);
                    console.log(restToMatch);
                    currNode = node;
                    foundNode = true;
                    break;
                } else if (!node.folder && restToMatch.startsWith(node.file + "/")) {
                    return utils.errors.FILE_NOT_DIRECTORY;
                } else if (!node.folder && restToMatch === node.file) {
                    return node;
                }
            }
        }

        return utils.errors.FILE_NOT_FOUND;
    },
    sourceTree: function parseSourceTree(fileTree: LibrariesTree) {
        // Filter the jars directory out of the file tree data src file data before being parsed
        const JARS_DIR = '/jars';
        fileTree.src = fileTree.src.filter(function (node) {
            return node.indexOf(JARS_DIR) !== 0;
        });

        srcFiles = parse._tree(fileTree.src, 'src');

        return srcFiles;
    },
    librariesTree: function parseLibrariesTree(fileTree: LibrariesTree) {
        jarFiles = parse._tree(fileTree.jars, 'jars');
        return jarFiles;
    },

    _tree: function parseFileTree(fileTree: string[], fileNamespace: string) {

        const stage1Output: FileTrie = new Map<string, Map<string, FileTrie>>();

        fileTree.forEach(function (element: string) {
            const array = element.substring(1).split('/');
            let lastState2 = stage1Output;

            array.forEach(function(value) {
                if (!lastState2.has(value)) {
                    lastState2.set(value, new Map<string, FileTrie>());
                }
                lastState2 = lastState2.get(value);
            });
        });

        const validFiles: string[] = [];

        function stage2Parser(prop: FileTrie, href: string, fileNamespace: string, parentNode: Node) {
            const resultsFiles = [];
            const resultsFolder = [];

            for (const attr of prop.keys()) {
                const hasExtension = (ext: string): boolean => {
                    return attr.indexOf(ext, attr.length - ext.length) !== -1;
                }

                const iconForFile = () => {
                    if (hasExtension('.java')) {
                        return 'fa fa-file-code-o';
                    } else if (hasExtension('.zip')
                        || hasExtension('.jar') || hasExtension('.aar')) {
                        return 'fa fa-archive';
                    } else if (hasExtension('.txt') || hasExtension('.md')) {
                        return 'fa fa-file-text';
                    } else {
                        return 'fa fa-question';
                    }
                };

                if (attr === '' || hasExtension('.tmp')) continue;

                const location = fileNamespace + '/';
                let items: Node = {
                    text: attr,
                    file: attr,
                    folder: false,
                    icon: iconForFile(),
                    parentFile: location,
                    parent: JSON.stringify(parentNode),
                    href: undefined,
                };

                const child = prop.get(attr);
                const childEntries = [...child.values()];
                if (childEntries.length > 0) { // detect folders
                    const children = stage2Parser(child, href, location + attr, items);
                    // We don't want the default '#' behavior, so literally do nothing
                    items.href = 'javaScript:void(0);';
                    items.file = items.text;
                    // Change item to have a folder icon
                    items.icon = 'fa fa-folder';
                    items.folder = true;
                    items.nodes = children;

                    // Check if nodes has only one child, if so rename to package layout
                    if (items.nodes.length === 1) {
                        const nodeToMerge = items.nodes[0];
                        if (nodeToMerge.nodes) { // don't merge if nodeToMerge isn't also a parent
                            items = {
                                text: items.text + '.' + nodeToMerge.text,
                                nodes: nodeToMerge.nodes,
                                href: nodeToMerge.href,
                                parentFile: nodeToMerge.parentFile,
                                file: nodeToMerge.file,
                                icon: 'fa fa-folder',
                                parentNode: nodeToMerge.parentNode,
                                folder: true,
                                parent: nodeToMerge.parent
                            };
                        }
                    }

                    resultsFolder.push(items);
                } else { // file
                    validFiles.push('/' + location + attr);
                    if (attr.endsWith('.jar') || attr.endsWith('.aar')) {
                        items.href = 'javaScript:void(0);';
                    } else {
                        items.href = href + '/' + location + attr;
                    }
                    resultsFiles.push(items);
                }
            }

            const nodeSortFn = function (a: Node, b: Node) {
                return a.text.localeCompare(b.text);
            };

            resultsFolder.sort(nodeSortFn);
            resultsFiles.sort(nodeSortFn);
            return resultsFolder.concat(resultsFiles);

        }

        const fileGetUri = utils.javaUrlRoot + '/editor.html?';
        const ret = stage2Parser(stage1Output, fileGetUri, fileNamespace, null);
        console.log(validFiles);
        return ret;
    }
};

export function get(callback: (arg0: Node[], arg1: () => void) => void, callbackFinished: () => void): void {
    // Some logic to retrieve, or generate tree structure
    const treeUri = env.urls.URI_FILE_TREE;

    $.get(treeUri, function (data) {
        callback(parse.sourceTree(data), callbackFinished);
    }).fail(function () {
        console.error("Getting file tree failed!");
    });
}
