import ace from 'ace-builds/src-noconflict/ace';

const themeColors = ace.require('ace/theme/obj').color;

const env = window.env;

function cssEngine(rule: string): void {
    const css = document.createElement('style'); // Creates <style></style>
    css.type = 'text/css'; // Specifies the type
    css.appendChild(document.createTextNode(rule)); // Support for the rest
    document.getElementsByTagName('head')[0].appendChild(css); // Specifies where to place the css
}

export const backColor = themeColors.primary_1;
export const handleColor = themeColors.primary_3;
export const hoverColor = themeColors.marker_layer_active_line_back;
export const gutterColor = themeColors.gutter_back;
cssEngine(`
    #menu-container .nav>li>a:hover { background-color: '${hoverColor}'; }

    .ace-${env.editorTheme} .ace_gutter {
        background: ${backColor};
    }

    #open-files .file-tab.active-tab {
        background: ${backColor}
    }

    #left-pane, #file-tree .node-file-tree, #left-pane-handle, #build-log-handle {
        background-color: ${handleColor};
    }
`)