import $ from "jquery";

declare type Key = {
    pressed: boolean;
    code: number;
    keyName: string;
}
declare type KeyCombo = {
    keys: string[];
    callback: (evt: JQuery.KeyDownEvent<Window, undefined, Window, Window>) => void;
}
declare type KeyEvent = 'up' | 'down';

const monitoredKeyNames: string[] = [];
const monitoredKeys: Key[] = [];
const keyCombos: KeyCombo[] = [];
function monitorKey(keyCode: number, keyName: string): Key {
    monitoredKeyNames.push(keyName);
    const key = {
        keyName: keyName,
        pressed: false,
        code: keyCode
    };
    monitoredKeys.push(key);
    return key;
}

export function monitorKeyCombo(keysInCombo: string[], callback: () => void): boolean {
    if (!Array.isArray(keysInCombo) || typeof callback !== 'function') {
        return false;
    }
    keyCombos.push({keys: keysInCombo, callback: callback});
    return true;
}

export const keys = {
    ctrl: monitorKey(17, 'ctrl'),
    alt: monitorKey(18, 'alt'),
    shift: monitorKey(16, 'shift'),
    space: monitorKey(32, 'space'),
    enter: monitorKey(13, 'enter'),

    monitoredKeyNames: monitoredKeyNames,
    monitoredKeys: monitoredKeys,
    numberOfKeysPressed: 0
};

function normalizeModifierKey(key: Key, isPressed: boolean, keyEvent: KeyEvent) {
    const detectKeyDown = keyEvent === 'down' && (isPressed && !key.pressed);
    const detectKeyUp = keyEvent === 'up' && (!isPressed && key.pressed);
    key.pressed = isPressed;
    if (detectKeyDown) {
        keys.numberOfKeysPressed++;
    } else if (detectKeyUp) {
        keys.numberOfKeysPressed--;
    }
}

$(window).on('keydown',  (evt) => {
    // Normalize the modifiers key, in case we have not received the keydown events
    normalizeModifierKey(keys.ctrl, evt.ctrlKey, 'down');
    normalizeModifierKey(keys.alt, evt.altKey, 'down');
    normalizeModifierKey(keys.shift, evt.shiftKey, 'down');

    for (const key of keys.monitoredKeys) {
        if (key.keyName === 'ctrl' || key.keyName === 'alt' || key.keyName === 'shift') {
            continue;
        }
        // todo: change evt.which to evt.key, when evt.key support is better
        if (evt.which === key.code) {
            key.pressed = true;
            keys.numberOfKeysPressed++;
            break;
        }
    }

    for (const combo of keyCombos) {
        let isValidCombo = true;

        for (const testKey of keys.monitoredKeys) {
            const indexOfComboKey = combo.keys.indexOf(testKey.keyName);
            if ((indexOfComboKey < 0 && testKey.pressed) || // key not wanted, but pressed
                (indexOfComboKey >= 0 && !testKey.pressed)) { // wanted key, but not pressed
                isValidCombo = false;
                break;
            }
        }

        if (isValidCombo) {
            combo.callback(evt);
            break;
        }
    }
});

$(window).on('keyup', (evt) => {
    for (const key of keys.monitoredKeys) {
        if (key.keyName === 'ctrl' || key.keyName === 'alt' || key.keyName === 'shift') continue;
        if (evt.which === key.code) {
            key.pressed = false;
            keys.numberOfKeysPressed--;
            break;
        }
    }

    // Normalize the modifiers key, in case we have not received the keyup events
    normalizeModifierKey(keys.ctrl, evt.ctrlKey, 'up');
    normalizeModifierKey(keys.alt, evt.altKey, 'up');
    normalizeModifierKey(keys.shift, evt.shiftKey, 'up');
});
